extern int nglGetScreenWidth();
extern int nglGetScreenHeight();
extern void ksnglSetPerspectiveMatrix(float, float, float, float, float);

enum game_state_e
{
  GSTATE_NONE,
  GSTATE_PLAY_INTRO_MOVIES,
  GSTATE_FRONT_END,
  GSTATE_LOAD_LEVEL,
  GSTATE_PLAY_MOVIE,
  GSTATE_RUNNING,
  GSTATE_PLAY_FE_MOVIE
};

class game
{
public:
  enum RENDER_STATE
  {
    GAME_RENDER_LOADING_LEVEL,
    GAME_RENDER_INITALIZE_FE,
    GAME_RENDER_DRAW_FE,
    GAME_RENDER_GAME_LEVEL
  };

  int get_cur_state() const;
  RENDER_STATE get_render_state() { return renderState; };
  float get_field_of_view() { return field_of_view; };
  void render_map_screen();
  void render_legal_screen();
  void render_fe();
  void render_level();
  void render();

private:
  char prefix[0x44];
  float field_of_view;
  char middle[0x28];
  RENDER_STATE renderState;
};

#define assert(x) ((void)0)

void game::render()
{
	ksnglSetPerspectiveMatrix(get_field_of_view(), nglGetScreenWidth()/2, nglGetScreenHeight()/2, 0.2f, 1200.0f);	 // set a decent far and near plane
	if(get_cur_state() == GSTATE_PLAY_INTRO_MOVIES || get_cur_state() == GSTATE_PLAY_FE_MOVIE)
	{
		return;
	}

	switch (get_render_state())
	{
	case GAME_RENDER_LOADING_LEVEL:
		render_map_screen(); break;
	case GAME_RENDER_INITALIZE_FE:
		render_legal_screen(); break;
	case GAME_RENDER_DRAW_FE:
		render_fe(); break;
	case GAME_RENDER_GAME_LEVEL:
		render_level(); break;
	default:
		assert("Hitting render loop in bad state");
		break;
	}

}
